INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-200019, now(), now(), 'seed', '<h2>سياسة الخصوصية</h2><p>شركة Egypt Car Sales، 123 شارع أوتو رود، القاهرة، هي المسؤولة عن معالجة بياناتك.</p><h3>البيانات التي نجمعها</h3><ul><li>الاسم ورقم الهاتف والرقم القومي لإجراءات الترخيص</li><li>بيانات التمويل التي يطلبها البنك الشريك</li><li>سجل زيارات الصيانة والفحص</li></ul><h3>مدة الاحتفاظ</h3><p>نحتفظ بمستندات البيع عشر سنوات وفقًا لالتزاماتنا الضريبية، وببيانات الحساب ثلاث سنوات من آخر نشاط.</p><h3>حقوقك</h3><p>يمكنك طلب الاطلاع أو التصحيح أو الحذف عبر <a href="mailto:privacy@egyptcarsales.com">privacy@egyptcarsales.com</a>.</p>', 'سياسة الخصوصية', 'سياسة الخصوصية', null, null, null, null, 'ar', -20010, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-200020, now(), now(), 'seed', '<h2>Politique de confidentialité</h2><p>Egypt Car Sales, 123 Auto Road, Le Caire, est responsable du traitement de vos données.</p><h3>Données collectées</h3><ul><li>Nom, téléphone et numéro national pour les formalités d''immatriculation</li><li>Données de financement exigées par la banque partenaire</li><li>Historique des passages en atelier et des inspections</li></ul><h3>Conservation</h3><p>Les documents de vente sont conservés dix ans au titre de nos obligations fiscales, les données de compte trois ans après la dernière activité.</p><h3>Vos droits</h3><p>Accès, rectification et effacement s''exercent auprès de <a href="mailto:privacy@egyptcarsales.com">privacy@egyptcarsales.com</a>.</p>', 'Politique de confidentialité', 'Politique de confidentialité', null, null, null, null, 'fr', -20010, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.policy_version (id, store_merchant_id, content_id, version, status, effective_from, note, translations, published_at, published_by)
