INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-200021, now(), now(), 'seed', '<h2>سياسة الإرجاع</h2><p>السيارات الجديدة تخضع لضمان الوكيل. أما السيارات المستعملة فلها سبعة أيام أو 300 كيلومتر، أيهما أقرب.</p><h3>ما يشمله الضمان</h3><ul><li>المحرك وناقل الحركة لمدة ستة أشهر</li><li>الأعطال المخالفة لتقرير الفحص المسلَّم إليك</li></ul><h3>ما لا يشمله</h3><ul><li>قطع الاستهلاك: الإطارات، الفرامل، البطارية</li><li>الأضرار الناتجة عن حادث أو سوء استخدام</li></ul><p><em>النسخة الثانية — رفعنا المدة من ثلاثة أيام إلى سبعة.</em></p>', 'سياسة الإرجاع والضمان', 'سياسة الإرجاع والضمان', null, null, null, null, 'ar', -20011, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-200022, now(), now(), 'seed', '<h2>Politique de retour</h2><p>Les véhicules neufs sont couverts par la garantie constructeur. Les véhicules d''occasion disposent de sept jours ou 300 kilomètres, au premier des deux termes atteint.</p><h3>Ce que couvre la garantie</h3><ul><li>Moteur et boîte de vitesses pendant six mois</li><li>Tout défaut contredisant le rapport d''inspection qui vous a été remis</li></ul><h3>Ce qu''elle ne couvre pas</h3><ul><li>Pièces d''usure : pneumatiques, freins, batterie</li><li>Dommages liés à un accident ou à un mauvais usage</li></ul><p><em>Version 2 — le délai passe de trois à sept jours.</em></p>', 'Politique de retour et garantie', 'Politique de retour et garantie', null, null, null, null, 'fr', -20011, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.policy_version (id, store_merchant_id, content_id, version, status, effective_from, note, translations, published_at, published_by)
VALUES (-2002, '65f023632bc26470c104b75f', -20011, 1, 'ARCHIVED', now() - interval '400 days', 'Initial version', '[{"language": "ar", "title": "سياسة الإرجاع والضمان", "body": "<h2>سياسة الإرجاع</h2><p>ثلاثة أيام أو 150 كيلومترًا للسيارات المستعملة.</p><p><em>النسخة الأولى — مؤرشفة.</em></p>", "state": "TRANSLATED"}, {"language": "fr", "title": "Politique de retour et garantie", "body": "<h2>Politique de retour</h2><p>Trois jours ou 150 kilomètres pour les véhicules d''occasion.</p><p><em>Version 1 — archivée.</em></p>", "state": "TRANSLATED"}]', now(), 'seed')
on conflict (id) do nothing;
