INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-200023, now(), now(), 'seed', '<h2>التسليم</h2><p>التسليم يتم من المعرض أو أمام باب منزلك داخل الجمهورية.</p><table><tr><th>الوجهة</th><th>المدة</th><th>التكلفة</th></tr><tr><td>القاهرة الكبرى</td><td>يوم إلى يومين</td><td>مجانًا</td></tr><tr><td>الإسكندرية والدلتا</td><td>يومان إلى ثلاثة</td><td>1500 جنيه</td></tr><tr><td>الصعيد والبحر الأحمر</td><td>ثلاثة إلى خمسة أيام</td><td>2500 جنيه</td></tr></table><p>لا تُسلَّم أي سيارة قبل استكمال الترخيص ونقل الملكية.</p>', 'سياسة التسليم', 'سياسة التسليم', null, null, null, null, 'ar', -20012, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-200024, now(), now(), 'seed', '<h2>Livraison</h2><p>La livraison se fait au showroom ou devant chez vous, partout en Égypte.</p><table><tr><th>Destination</th><th>Délai</th><th>Tarif</th></tr><tr><td>Grand Caire</td><td>1 à 2 jours</td><td>Offerte</td></tr><tr><td>Alexandrie et Delta</td><td>2 à 3 jours</td><td>1 500 EGP</td></tr><tr><td>Haute-Égypte et mer Rouge</td><td>3 à 5 jours</td><td>2 500 EGP</td></tr></table><p>Aucun véhicule n''est livré avant l''immatriculation et le transfert de propriété.</p>', 'Politique de livraison', 'Politique de livraison', null, null, null, null, 'fr', -20012, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.policy_version (id, store_merchant_id, content_id, version, status, effective_from, note, translations, published_at, published_by)
VALUES (-2004, '65f023632bc26470c104b75f', -20012, 1, 'LIVE', now() - interval '30 days', null, '[{"language": "ar", "title": "سياسة التسليم", "body": "<h2>التسليم</h2><p>التسليم يتم من المعرض أو أمام باب منزلك داخل الجمهورية.</p><table><tr><th>الوجهة</th><th>المدة</th><th>التكلفة</th></tr><tr><td>القاهرة الكبرى</td><td>يوم إلى يومين</td><td>مجانًا</td></tr><tr><td>الإسكندرية والدلتا</td><td>يومان إلى ثلاثة</td><td>1500 جنيه</td></tr><tr><td>الصعيد والبحر الأحمر</td><td>ثلاثة إلى خمسة أيام</td><td>2500 جنيه</td></tr></table><p>لا تُسلَّم أي سيارة قبل استكمال الترخيص ونقل الملكية.</p>", "state": "TRANSLATED"}, {"language": "fr", "title": "Politique de livraison", "body": "<h2>Livraison</h2><p>La livraison se fait au showroom ou devant chez vous, partout en Égypte.</p><table><tr><th>Destination</th><th>Délai</th><th>Tarif</th></tr><tr><td>Grand Caire</td><td>1 à 2 jours</td><td>Offerte</td></tr><tr><td>Alexandrie et Delta</td><td>2 à 3 jours</td><td>1 500 EGP</td></tr><tr><td>Haute-Égypte et mer Rouge</td><td>3 à 5 jours</td><td>2 500 EGP</td></tr></table><p>Aucun véhicule n''est livré avant l''immatriculation et le transfert de propriété.</p>", "state": "TRANSLATED"}]', now(), 'seed')
