INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-200025, now(), now(), 'seed', '<h2>ملفات تعريف الارتباط</h2><p>نستخدم ثلاث فئات، واحدة منها فقط لا تحتاج موافقتك.</p><ul><li><strong>أساسية</strong> — الجلسة والمقارنة والأمان. تعمل دائمًا.</li><li><strong>قياس</strong> — إحصاءات مجمّعة، ثلاثة عشر شهرًا.</li><li><strong>تخصيص</strong> — اقتراح سيارات مشابهة، ستة أشهر.</li></ul><p>يُحفظ اختيارك ستة أشهر ويمكن تعديله من رابط « تفضيلات الكوكيز » أسفل الصفحة.</p>', 'سياسة ملفات تعريف الارتباط', 'سياسة ملفات تعريف الارتباط', null, null, null, null, 'ar', -20013, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-200026, now(), now(), 'seed', '<h2>Cookies</h2><p>Nous utilisons trois familles, dont une seule est exemptée de consentement.</p><ul><li><strong>Essentiels</strong> — session, comparateur, sécurité. Toujours actifs.</li><li><strong>Mesure</strong> — statistiques agrégées, 13 mois.</li><li><strong>Personnalisation</strong> — suggestions de véhicules similaires, 6 mois.</li></ul><p>Votre choix est conservé six mois et modifiable depuis « Préférences cookies » en pied de page.</p>', 'Politique relative aux cookies', 'Politique relative aux cookies', null, null, null, null, 'fr', -20013, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.policy_version (id, store_merchant_id, content_id, version, status, effective_from, note, translations, published_at, published_by)
VALUES (-2005, '65f023632bc26470c104b75f', -20013, 1, 'LIVE', now() - interval '30 days', null, '[{"language": "ar", "title": "سياسة ملفات تعريف الارتباط", "body": "<h2>ملفات تعريف الارتباط</h2><p>نستخدم ثلاث فئات، واحدة منها فقط لا تحتاج موافقتك.</p><ul><li><strong>أساسية</strong> — الجلسة والمقارنة والأمان. تعمل دائمًا.</li><li><strong>قياس</strong> — إحصاءات مجمّعة، ثلاثة عشر شهرًا.</li><li><strong>تخصيص</strong> — اقتراح سيارات مشابهة، ستة أشهر.</li></ul><p>يُحفظ اختيارك ستة أشهر ويمكن تعديله من رابط « تفضيلات الكوكيز » أسفل الصفحة.</p>", "state": "TRANSLATED"}, {"language": "fr", "title": "Politique relative aux cookies", "body": "<h2>Cookies</h2><p>Nous utilisons trois familles, dont une seule est exemptée de consentement.</p><ul><li><strong>Essentiels</strong> — session, comparateur, sécurité. Toujours actifs.</li><li><strong>Mesure</strong> — statistiques agrégées, 13 mois.</li><li><strong>Personnalisation</strong> — suggestions de véhicules similaires, 6 mois.</li></ul><p>Votre choix est conservé six mois et modifiable depuis « Préférences cookies » en pied de page.</p>", "state": "TRANSLATED"}]', now(), 'seed')
